+
+impl NeckBands {
+    /// The neck `stack` carries for the shank of `g`, or `None` when the
+    /// laws read the stated shank cylinder there.
+    #[must_use]
+    pub fn of(g: &ToolGeom, stack: &HolderStack) -> Option<Self> {
