+            *slot = *band;
+        }
+        out.n = bands.len();
+        Some(out)
+    }
+
+    /// The bands, bottom-up.
+    #[must_use]
+    pub fn bands(&self) -> &[HolderBand] {
+        &self.b[..self.n]
+    }
+
+    /// Does this neck still fit the shank of `g` exactly as carried?
+    #[must_use]
